#!/bin/bash
set -eo pipefail
umask 077
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_BODY_DEPLOY'
import base64,hashlib,io,json,os,pathlib,shutil,subprocess,sys,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/vegetation_body_acquisition_v1')
assert root.parent.resolve(strict=True)==root.parent and not root.exists() and not root.is_symlink()
old=root.parent/'missing_vegetation_xml_v1'
assert json.loads((old/'CONTROL_RESULT.json').read_bytes())['metadata_complete_accepted'] is True
assert shutil.disk_usage(root.parent).free>=8*1024**3
packed=base64.b64decode('',validate=True)
assert len(packed)==117451 and hashlib.sha256(packed).hexdigest()=='36f2ba302b986bef593ea975a28bf302059a0cd585f4fa744c81e8555445de98'
table=json.loads('{"VEGETATION_BODY_CONTRACT.json":{"bytes":1127946,"sha256":"652be55ddf97eec773cff1ac99f9dab6e45828d023a8e2a60a808699084830fd"},"acquire_vegetation_bodies_v1.py":{"bytes":14856,"sha256":"ebf2072f1ad6da228ce4a75457027f1c0c1724997953a915f55d5924db35d79a"},"vegetation_body_transport_v1.py":{"bytes":2732,"sha256":"eff140a6a0ee6c97984831d0caa7a2cc5f67274a40369e089c703f4e0ec4c789"},"vegetation_body_control_v1.py":{"bytes":5980,"sha256":"066a1f4433d2d34590d457b869c2718d86661f68ca9cdca8b5089e4a02552efb"},"catalog_semantics.py":{"bytes":1904,"sha256":"98db5e719d32f41ec36bbca4c2864b095c811f820fb88b9df24baee24ef9031c"},"ENTRY_TABLE.json":{"bytes":712,"sha256":"c211f4883b83192290ccff56534a82629d9ccbd383a12602bf6e0cd15ff15da2"}}')
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 assert archive.namelist()==sorted(table) and len(archive.namelist())==6
 assert sum(x.file_size for x in archive.infolist())<=8*1024**2
 values={}
 for name in archive.namelist():
  assert pathlib.PurePosixPath(name).name==name and not name.startswith('.')
  raw=archive.read(name);assert len(raw)==table[name]['bytes'] and hashlib.sha256(raw).hexdigest()==table[name]['sha256']
  values[name]=raw
root.mkdir(mode=0o700)
for name in ('requests','bodies'): (root/name).mkdir(mode=0o700)
for name,raw in values.items():
 with (root/name).open('xb') as stream:stream.write(raw)
with (root/'LAUNCH_REQUESTED.json').open('x') as stream:
 json.dump(dict(one_launch_only=True,automatic_retries=0,scientific_array_reads=0,new_slurm_jobs=0),stream)
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='',
 OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1',NUMEXPR_NUM_THREADS='1')
argv=[sys.executable,'-B',str(root/'vegetation_body_control_v1.py')]
with (root/'control.stdout').open('xb') as out,(root/'control.stderr').open('xb') as err:
 process=subprocess.Popen(argv,cwd=root,env=env,stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
ticks=None
try:
 value=(pathlib.Path('/proc')/str(process.pid)/'stat').read_text();ticks=value[value.rfind(')')+2:].split()[19]
except FileNotFoundError:pass
with (root/'LAUNCH.json').open('x') as stream:
 json.dump(dict(pid=process.pid,argv=argv,start_ticks=ticks,remote_root=str(root),hard_child_seconds=3660,
  acceptance_seconds=3600,automatic_retries=0,new_slurm_jobs=0),stream,indent=2)
print('OWN_BODY_PAYLOAD_VERIFIED=6')
print('OWN_BODY_PARENT_PID='+str(process.pid))
print('OWN_BODY_LAUNCH_DONE')
PY_BODY_DEPLOY
